// Native touch/trackpad scrolling plus mouse grab-to-scroll; a drag never selects a card.
function bindHorizontalScroll(el,snap=false){if(!el)return;let start=null,dragged=false,blockClickUntil=0;
 el.addEventListener('dragstart',e=>e.preventDefault());
 el.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;start={x:e.clientX,left:el.scrollLeft,id:e.pointerId};dragged=false;});
 el.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x;if(!dragged&&Math.abs(dx)>6){dragged=true;el.setPointerCapture(e.pointerId);el.classList.add('dragging');}if(dragged){e.preventDefault();el.scrollLeft=start.left-dx;}});
 const end=e=>{if(!start)return;const wasDragged=dragged;start=null;el.classList.remove('dragging');if(el.hasPointerCapture?.(e.pointerId))el.releasePointerCapture(e.pointerId);if(wasDragged){blockClickUntil=Date.now()+350;if(snap)el.scrollTo({left:Math.round(el.scrollLeft/el.clientWidth)*el.clientWidth,behavior:'smooth'});}};
 el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('pointerleave',e=>{if(!dragged)start=null;});
 el.addEventListener('click',e=>{if(Date.now()<blockClickUntil){e.preventDefault();e.stopPropagation();}},true);
}
function bindIntro(){const el=document.querySelector('.intro-slides');if(!el)return;el.scrollLeft=introIndex*el.clientWidth;bindHorizontalScroll(el,true);
 el.addEventListener('scroll',()=>{introIndex=Math.max(0,Math.min(2,Math.round(el.scrollLeft/el.clientWidth)));document.querySelectorAll('.intro-dots button').forEach((b,i)=>{b.classList.toggle('active',i===introIndex);b.setAttribute('aria-current',i===introIndex?'step':'false');});},{passive:true});
 el.addEventListener('keydown',e=>{if(e.target!==el||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();introIndex=Math.max(0,Math.min(2,introIndex+(e.key==='ArrowRight'?1:-1)));el.scrollTo({left:introIndex*el.clientWidth,behavior:'smooth'});});
}
